jQuery(document).ready(function($){let isScrolling=!1;$(".cos-slider-novedades .tab-option").click(function(){let $container=$(this).closest(".cos-slider-novedades");$container.find(".tab-option").removeClass("active");$(this).addClass("active");let tabIndex=$(this).attr("data-tab");$container.find(".tab-option-content").removeClass("active");let $tab=$container.find(".tab-option-content[data-index="+tabIndex+"]");$tab.addClass("active");$tab.find(".color-thumb-list").slick("refresh");$(".slider-carousel-ambientes .slider-container").slick("refresh")});const carousels=document.querySelectorAll(".slider-carousel-ambientes .slider-container");if(!carousels||carousels.length===0){return}
carousels.forEach((element)=>{const arrowLeft=element.parentElement.querySelector(".slider-carousel-ambientes .btn-prev");const arrowRight=element.parentElement.querySelector(".slider-carousel-ambientes .btn-next");const slickOptions={infinite:!1,autoplay:!1,dots:!1,arrows:!0,fade:!1,centerMode:!1,prevArrow:arrowLeft,nextArrow:arrowRight,slidesToShow:1,slidesToScroll:1,};const slickedElement=$(element).slick(slickOptions);window.addEventListener("resize",function(e){if(!slickedElement.hasClass("slick-initialized")){slickedElement.slick(slickOptions)}})});$(".slider-carousel-ambientes").lightGallery({selector:".slider-carousel-ambientes A.project-slide-item",thumbnail:!0,animateThumb:!1,loop:!1,showThumbByDefault:!0,download:!1,googlePlus:!1,});$(".slider-carousel-ambientes .btn-expand").click(function(e){let $gallery=$(this).closest(".slider-carousel-ambientes");$gallery.find("A.slick-active").click()});window.addEventListener("scroll",function(){section=document.querySelector(".tab-option-content");position=section.getBoundingClientRect();if(position.top+200<window.innerHeight&&position.bottom>=0&&isScrolling==!1){setTimeout(function(){$(".tab-navigation").animate({scrollLeft:"+=70"},1000)},200);setTimeout(function(){$(".tab-navigation").animate({scrollLeft:"-=70"},1000)},1000);isScrolling=!0}else if(position.bottom<0){isScrolling=!1}})})